\quad Let $y=\sqrt[x]{f(x)}$. Then one can get
\begin{equation*}
y'=\frac{y}{x}\left(\frac{f'(x)}{f(x)}-\frac{\log{f(x)}}{x}\right).
\end{equation*}
In order to show that $\sqrt[x]{f(x)}$ is strictly increasing, it
suffices to prove
\begin{equation}\label{e1}
\frac{f'(x)}{f(x)}-\frac{\log{f(x)}}{x}>0
\end{equation}
for $x\geq N$. Since $f(N)\leq 1$ and $f(x)$ is increasing, one can
derive that
\begin{equation}\label{e2}
\frac{\log{f(x)}}{x}\leq\frac{\log{f(x)}-\log{f(N)}}{x}<\frac{\log{f(x)}-\log{f(N)}}{x-N}
\end{equation}
for $x\geq N$.

 By the mean value theorem, one can obtain
\begin{equation}\label{e3}
\frac{\log{f(x)}-\log{f(N)}}{x-N}=\frac{f'(\xi)}{f(\xi)},
\end{equation}
where $N\leq\xi\leq x$. On the other hand, it follows from
log-convexity of the function $f(x)$ that
\begin{equation}
\left(\log{f(x)}\right)''=\left(\frac{f'(x)}{f(x)}\right)'=\frac{f''(x)f(x)-f'(x)^2}{f^2(x)}\geq0,
\end{equation}
which implies that $\frac{f'(x)}{f(x)}$ is increasing. Thus,  it
follows that
\begin{equation}\label{e4}
\frac{f'(\xi)}{f(\xi)}\leq\frac{f'(x)}{f(x)}
\end{equation}
for $x\geq\xi.$ Combining (\ref{e2}), (\ref{e3}) and (\ref{e4}), one
can obtain (\ref{e1}). So $\sqrt[x]{f(x)}$ is increasing.

\label{bound+gama}
Let $a>0$. Assume that $h(x)=\log{\Gamma(x)}$. If $b\geq -1$ and
$ax+b\geq0$, then
\begin{eqnarray*}
x^3\left(\frac{h(ax+b+1)}{x}\right)''&\leq&-ax+(2b+1)\log{(ax+b+1)}-3b-\frac{3}{2}+\log{2\pi}+\frac{b^2+b+1/2}{ax+b+1};\\
x^3\left(\frac{h(ax+b+1)}{x}\right)''&\geq&-ax+(2b+1)\log{(ax+b+1)}-3b-3+\log{2\pi}.
\end{eqnarray*}

By $h(x)=\log{\Gamma(x)}$, it is not hard to deduce that
\begin{eqnarray*}
\left(\frac{h(ax+b+1)}{x}\right)''=\frac{a^2x^2h''(ax+b+1)-2axh'(ax+b+1)+2h(ax+b+1)}{x^3}.
\end{eqnarray*}
By (\ref{gama+1}), (\ref{gama+2}) and (\ref{gama+3}), it follows
that
\begin{eqnarray*}
&&a^2x^2h''(ax+b+1)-2axh'(ax+b+1)+2h(ax+b+1)\\
&\leq&-ax+(2b+1)\log{(ax+b+1)}-3b-\frac{3}{2}+\log{2\pi}+\frac{b^2+b+1/2}{ax+b+1}.
\end{eqnarray*}
In addition, by (\ref{gama+4}), (\ref{gama+5}) and (\ref{gama+6}),
one can also obtain that
\begin{eqnarray*}
&&a^2x^2h''(ax+b+1)-2axh'(ax+b+1)+2h(ax+b+1)\\
&\geq&-ax+(2b+1)\log{(ax+b+1)}-3b-3+\log{2\pi}.
\end{eqnarray*}
This completes the proof.

\label{thm+e}
Let $n_{0},k_{0},\overline{k_0}$ be nonnegative integers and
$a,b,\overline{b}$ be positive integers. Define the function
\begin{eqnarray*}
G(x)=\frac{\Gamma(n_{0}+ax+1)}{{\Gamma(k_{0}+bx+1)}
{\Gamma(\overline{k_{0}}+x\overline{b}+1)}}.
\end{eqnarray*}
If $a\geq b+\overline{b}$ and $-1\leq k_0-(n_0+1)b/a\leq0$, then
$(\log G(x))''$ is a completely monotonic function for $x\geq0$. In
particular,
$$\{\frac{(n_{0}+ia)!}{(k_0+ib)!(\overline{k_0}+i\overline{b})!}\}_{i\geq0}$$
is infinitely log-monotonic.

